CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE TYPE user_role AS ENUM ('SUPER_ADMIN','ADMIN','OPERATOR','ACCOUNTANT');
CREATE TYPE job_status AS ENUM ('RECEIVED','WAITING_FOR_DRYING','DRYING','DRYING_COMPLETED','WEIGHT_VERIFICATION','INVOICED','COMPLETED','CANCELLED');
CREATE TYPE measurement_type AS ENUM ('RECEIVED','PRE_DRYING','INTERMEDIATE','FINAL','REJECTED');
CREATE TYPE batch_status AS ENUM ('CREATED','DRYING','COMPLETED','CANCELLED');
CREATE TYPE invoice_status AS ENUM ('DRAFT','ISSUED','PARTIALLY_PAID','PAID','CANCELLED');
CREATE TYPE payment_method AS ENUM ('CASH','UPI','BANK_TRANSFER','CARD','CREDIT');
CREATE TYPE notification_channel AS ENUM ('WHATSAPP','SMS');
CREATE TYPE notification_status AS ENUM ('PENDING','SENT','FAILED');
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, email text NOT NULL UNIQUE, phone text, password_hash text NOT NULL, role user_role NOT NULL, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_code text NOT NULL UNIQUE, name text NOT NULL, phone text NOT NULL, whatsapp_number text, address text, village text, district text, gst_number text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX customers_phone_idx ON customers(phone); CREATE INDEX customers_name_idx ON customers(name);
CREATE TABLE drying_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_number text NOT NULL UNIQUE, customer_id uuid NOT NULL REFERENCES customers(id), product_type text NOT NULL DEFAULT 'CARDAMOM', status job_status NOT NULL, received_at timestamptz NOT NULL, expected_completion_at timestamptz, completed_at timestamptz, notes text, created_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX drying_jobs_customer_idx ON drying_jobs(customer_id); CREATE INDEX drying_jobs_status_idx ON drying_jobs(status); CREATE INDEX drying_jobs_received_idx ON drying_jobs(received_at);
CREATE TABLE weight_measurements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), drying_job_id uuid NOT NULL REFERENCES drying_jobs(id) ON DELETE CASCADE, measurement_type measurement_type NOT NULL, weight_kg numeric(12,3) NOT NULL CHECK(weight_kg>0), moisture_percentage numeric(5,2) CHECK(moisture_percentage BETWEEN 0 AND 100), measured_at timestamptz NOT NULL, measured_by uuid REFERENCES users(id), notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX measurements_job_idx ON weight_measurements(drying_job_id);
CREATE TABLE job_status_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), drying_job_id uuid NOT NULL REFERENCES drying_jobs(id) ON DELETE CASCADE, old_status job_status, new_status job_status NOT NULL, changed_by uuid REFERENCES users(id), reason text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE drying_batches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), batch_number text NOT NULL UNIQUE, drying_started_at timestamptz, drying_completed_at timestamptz, status batch_status NOT NULL DEFAULT 'CREATED', notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE drying_batch_jobs (batch_id uuid NOT NULL REFERENCES drying_batches(id) ON DELETE CASCADE, drying_job_id uuid NOT NULL REFERENCES drying_jobs(id), input_weight_kg numeric(12,3) NOT NULL CHECK(input_weight_kg>0), PRIMARY KEY(batch_id,drying_job_id));
CREATE TABLE pricing_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, charge_type text NOT NULL, product_type text, unit text NOT NULL, rate numeric(12,2) NOT NULL CHECK(rate>=0), effective_from timestamptz NOT NULL, effective_to timestamptz, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE charges (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), drying_job_id uuid NOT NULL REFERENCES drying_jobs(id) ON DELETE CASCADE, charge_type text NOT NULL, description text NOT NULL, quantity numeric(12,3) NOT NULL, unit text NOT NULL, rate numeric(12,2) NOT NULL, amount numeric(12,2) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_number text NOT NULL UNIQUE, drying_job_id uuid NOT NULL UNIQUE REFERENCES drying_jobs(id), customer_id uuid NOT NULL REFERENCES customers(id), subtotal numeric(12,2) NOT NULL, discount numeric(12,2) NOT NULL DEFAULT 0, tax_amount numeric(12,2) NOT NULL DEFAULT 0, total_amount numeric(12,2) NOT NULL, status invoice_status NOT NULL, issued_at timestamptz NOT NULL, due_at timestamptz, pdf_url text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX invoices_customer_idx ON invoices(customer_id); CREATE INDEX invoices_status_idx ON invoices(status);
CREATE TABLE invoice_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES invoices(id) ON DELETE CASCADE, description text NOT NULL, quantity numeric(12,3) NOT NULL, unit text NOT NULL, rate numeric(12,2) NOT NULL, amount numeric(12,2) NOT NULL);
CREATE TABLE payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES invoices(id), amount numeric(12,2) NOT NULL CHECK(amount>0), payment_method payment_method NOT NULL, transaction_reference text UNIQUE, paid_at timestamptz NOT NULL, received_by uuid REFERENCES users(id), notes text, created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX payments_invoice_idx ON payments(invoice_id);
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid REFERENCES customers(id), drying_job_id uuid REFERENCES drying_jobs(id), invoice_id uuid REFERENCES invoices(id), channel notification_channel NOT NULL, notification_type text NOT NULL, recipient text NOT NULL, message text NOT NULL, status notification_status NOT NULL, provider_message_id text, retry_count integer NOT NULL DEFAULT 0, sent_at timestamptz, failed_at timestamptz, error_message text, created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX notifications_status_idx ON notifications(status);
CREATE TABLE notification_templates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), notification_type text NOT NULL, channel notification_channel NOT NULL, template_name text NOT NULL, template_body text NOT NULL, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id), entity_type text NOT NULL, entity_id uuid NOT NULL, action text NOT NULL, old_data jsonb, new_data jsonb, ip_address text, created_at timestamptz NOT NULL DEFAULT now());
